+type InputTask = {
+  id: string;
+  duration: number;
+  dependsOn?: string[];
+};
+
+type Task = Required<InputTask>;
+
+export type Plan = {
+  order: string[];
+  layers: string[][];
+  earliest: Record<string, { start: number; finish: number }>;
+  totalDuration: number;
+  criticalPath: string[];
+};
+
+function fail(message: string): never {
+  throw new Error(message);
+}
+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+export function validateInput(value: unknown): Task[] {
+  if (!isRecord(value) || !Array.isArray(value.tasks)) {
+    fail('Invalid input: "tasks" must be an array.');
+  }
+
+  const tasks: Task[] = [];
+  const ids = new Set<string>();
+  for (let index = 0; index < value.tasks.length; index++) {
+    const candidate = value.tasks[index];
+    if (!isRecord(candidate)) fail(`Invalid task at index ${index}: expected an object.`);
+    if (typeof candidate.id !== "string" || candidate.id.length === 0) {
+      fail(`Invalid task at index ${index}: "id" must be a non-empty string.`);
+    }
+    if (ids.has(candidate.id)) fail(`Invalid input: duplicate task id "${candidate.id}".`);
+    if (typeof candidate.duration !== "number" || !Number.isFinite(candidate.duration) || candidate.duration < 0) {
+      fail(`Invalid task "${candidate.id}": "duration" must be a finite non-negative number.`);
+    }
+    const dependsOn = candidate.dependsOn === undefined ? [] : candidate.dependsOn;
+    if (!Array.isArray(dependsOn) || !dependsOn.every((dependency) => typeof dependency === "string")) {
+      fail(`Invalid task "${candidate.id}": "dependsOn" must be an array of strings.`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`Invalid task "${candidate.id}": "dependsOn" contains duplicate ids.`);
+    }
+    if (dependsOn.includes(candidate.id)) {
+      fail(`Invalid task "${candidate.id}": a task cannot depend on itself.`);
+    }
+    ids.add(candidate.id);
+    tasks.push({ id: candidate.id, duration: candidate.duration, dependsOn });
+  }
+
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) {
+      if (!ids.has(dependency)) fail(`Invalid task "${task.id}": unknown dependency "${dependency}".`);
+    }
+  }
+  return tasks;
+}
+
+function comparePaths(left: string[], right: string[]): number {
+  for (let index = 0; index < Math.min(left.length, right.length); index++) {
+    if (left[index] !== right[index]) return left[index] < right[index] ? -1 : 1;
+  }
+  return left.length - right.length;
+}
+
+export function planTasks(tasks: Task[]): Plan {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
+  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
+  }
+
+  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
+  const order: string[] = [];
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const dependent of dependents.get(id)!.sort()) {
+      const count = remaining.get(dependent)! - 1;
+      remaining.set(dependent, count);
+      if (count === 0) {
+        ready.push(dependent);
+        ready.sort();
+      }
+    }
+  }
+
+  if (order.length !== tasks.length) {
+    const state = new Map<string, "visiting" | "done">();
+    const stack: string[] = [];
+    const visit = (id: string): string[] | undefined => {
+      state.set(id, "visiting");
+      stack.push(id);
+      for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
+        if (state.get(dependency) === "visiting") return [...stack.slice(stack.indexOf(dependency)), dependency];
+        if (!state.has(dependency)) {
+          const cycle = visit(dependency);
+          if (cycle) return cycle;
+        }
+      }
+      stack.pop();
+      state.set(id, "done");
+      return undefined;
+    };
