+    const candidate = value.tasks[index];
+    if (!isRecord(candidate)) fail(`Invalid task at index ${index}: expected an object.`);
+    if (typeof candidate.id !== "string" || candidate.id.length === 0) {
+      fail(`Invalid task at index ${index}: "id" must be a non-empty string.`);
+    }
+    if (ids.has(candidate.id)) fail(`Invalid input: duplicate task id "${candidate.id}".`);
+    if (typeof candidate.duration !== "number" || !Number.isFinite(candidate.duration) || candidate.duration < 0) {
+      fail(`Invalid task "${candidate.id}": "duration" must be a finite non-negative number.`);
+    }
+    const dependsOn = candidate.dependsOn === undefined ? [] : candidate.dependsOn;
+    if (!Array.isArray(dependsOn) || !dependsOn.every((dependency) => typeof dependency === "string")) {
+      fail(`Invalid task "${candidate.id}": "dependsOn" must be an array of strings.`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`Invalid task "${candidate.id}": "dependsOn" contains duplicate ids.`);
+    }
+    if (dependsOn.includes(candidate.id)) {
