+      if (!state.has(id)) {
+        const cycle = visit(id);
+        if (cycle) fail(`Dependency cycle detected: ${cycle.join(" -> ")}`);
+      }
+    }
+  }
+
+  const earliest: Plan["earliest"] = {};
+  const layerById = new Map<string, number>();
+  const pathById = new Map<string, string[]>();
+  for (const id of order) {
+    const task = byId.get(id)!;
+    let start = 0;
+    let layer = 0;
+    let path: string[] = [id];
+    for (const dependency of task.dependsOn) {
+      const dependencyTiming = earliest[dependency];
+      start = Math.max(start, dependencyTiming.finish);
+      layer = Math.max(layer, layerById.get(dependency)! + 1);
+    }
+    for (const dependency of task.dependsOn) {
+      if (earliest[dependency].finish === start) {
+        const candidate = [...pathById.get(dependency)!, id];
+        if (comparePaths(candidate, path) < 0) path = candidate;
+      }
+    }
+    earliest[id] = { start, finish: start + task.duration };
+    layerById.set(id, layer);
+    pathById.set(id, path);
+  }
+
+  const layers: string[][] = [];
+  for (const id of order) {
+    const layer = layerById.get(id)!;
+    (layers[layer] ??= []).push(id);
+  }
+  for (const layer of layers) layer.sort();
+
+  let totalDuration = 0;
+  let criticalPath: string[] = [];
+  for (const id of [...order].sort()) {
+    const finish = earliest[id].finish;
+    const path = pathById.get(id)!;
+    if (finish > totalDuration || (finish === totalDuration && comparePaths(path, criticalPath) < 0)) {
+      totalDuration = finish;
+      criticalPath = path;
+    }
+  }
+  return { order, layers, earliest, totalDuration, criticalPath };
+}
+
+async function main(): Promise<void> {
+  const args = process.argv.slice(2);
+  if (args.length !== 2 || args[0] !== "plan") {
+    fail("Usage: bun run src/cli.ts plan INPUT.json");
+  }
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(await Bun.file(args[1]).text());
+  } catch (error) {
+    const detail = error instanceof Error ? error.message : String(error);
+    fail(`Unable to read valid JSON from "${args[1]}": ${detail}`);
+  }
+  process.stdout.write(`${JSON.stringify(planTasks(validateInput(parsed)))}\n`);
+}
+
+if (import.meta.main) {
+  main().catch((error: unknown) => {
+    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
+    process.exit(1);
+  });
+}

